const now = () => new Date().toISOString();
const clean = v => String(v ?? '').trim();
const json = (data,status=200) => new Response(JSON.stringify(data),{status,headers:JSON_HEADERS});
class ApiError extends Error { constructor(message,status=500,code='server_error'){super(message);this.status=status;this.code=code;} }
async function bodyJson(request){try{return await request.json();}catch{return {};}}
function keyOk(v){const s=clean(v);return !!s&&s.length<=200&&!/[\x00-\x1f]/.test(s);}
function slugOk(v){return /^[a-z0-9_-]{4,80}$/i.test(clean(v));}
function stripDiacritics(s){try{return s.normalize('NFD').replace(/[\u0300-\u036f]/g,'');}catch{return s;}}
function norm(s){
  let x=stripDiacritics(clean(s).toLowerCase());
  x=x.replace(/las vegas sports academy/g,' lvsa ').replace(/las vegas sports acad/g,' lvsa ');
  x=x.replace(/\bfootball club\b|\bsoccer club\b|\bsoccer academy\b/g,' ');
  x=x.replace(/\b(?:20)?\d{2}\s*[\/-]\s*(?:20)?\d{2}\b/g,' ');
  x=x.replace(/\b(?:u|bu|gu|b|g)?\d{2,4}\b/g,' ');
  x=x.replace(/\b(?:boys?|girls?|male|female|coed|co-ed|fc|sc|soccer|club|team|academy)\b/g,' ');
  return x.replace(/[^a-z0-9]+/g,' ').replace(/\s+/g,' ').trim();
}
