      if(res.ok&&Array.isArray(payload?.collection?.items)&&!payload.collection.error)return payload;
      if(res.status===401)error=new ApiError('TeamSnap authorization expired. Reconnect TeamSnap from /admin.',401,'teamsnap_auth_expired');
