  if(control.code==='teamsnap_auth_expired')throw new ApiError(control.message,401,'teamsnap_auth_expired');
  if(Number(control.next_retry_at)>Date.now())return {ok:true,queued:true,sync_status:'retry_wait',retry_at:control.next_retry_at,sync_error:control.message||null};
  const lease=new Date(Date.now()+TEAMSNAP_SYNC_LEASE_MS).toISOString()+'|'+crypto.randomUUID();
  const lock=await env.DB.prepare("INSERT INTO app_meta(key,value) VALUES('teamsnap_sync_lease',?) ON CONFLICT(key) DO UPDATE SET value=excluded.value WHERE app_meta.value<? RETURNING value").bind(lease,now()).first();
