  const statement=job?env.DB.prepare("INSERT INTO app_meta(key,value) VALUES('teamsnap_sync_job',?) ON CONFLICT(key) DO UPDATE SET value=excluded.value").bind(JSON.stringify(job)):env.DB.prepare("DELETE FROM app_meta WHERE key='teamsnap_sync_job'");
