async function traceHaloSingle(cookie,payload,runtime){haloReserve(runtime);const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),Math.max(1,Math.min(8000,runtime.deadline-Date.now())));try{const halo=await traceHaloRequest(cookie,payload,controller.signal);if(!Array.isArray(halo.ring))throw new ApiError('Trace returned an incomplete tracking result.',502,'trace_halo_invalid');runtime.chunks++;return[{status:'fulfilled',value:TraceSourceTools.extractSegmentsFromRing(halo.ring)}];}finally{clearTimeout(timer);}}
