   await env.DB.prepare('UPDATE trace_halo_tasks SET chunks_json=?,updated_at=? WHERE teamsnap_key=? AND game_id=? AND half=? AND member_gid=?').bind(JSON.stringify(chunks),now(),key,task.game_id,task.half,task.member_gid).run();
