  let responses;try{responses=runtime.mode==='single'?await traceHaloSingle(cookie,traceHaloPayload(member,clip,candidate,pending[0],'soccer'),runtime):await traceHaloBatch(cookie,pending.map(index=>traceHaloPayload(member,clip,candidate,index,'soccer')),runtime);}catch(e){if(e.code==='trace_halo_batch_unsupported'){runtime.mode='single';runtime.fallback=true;await env.DB.prepare("INSERT INTO app_meta(key,value) VALUES(?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value").bind('trace_batch_disabled:'+key,String(Date.now()+24*60*60*1000)).run();chunk=pending[0];continue;}throw e;}

